from http.server import HTTPServer, BaseHTTPRequestHandler
from pathlib import Path
from urllib.parse import urlparse,parse_qs
import json,time,html
from transit import predict
ROOT=Path(__file__).resolve().parents[1]
CSS='body{margin:0;background:#f4f7fb;font:17px -apple-system,BlinkMacSystemFont,Arial;color:#142d4d}header{background:#142d4d;color:white;padding:22px 4%}main{max-width:1250px;margin:25px auto}h1{font-size:30px;margin:0}h2{font-size:24px}nav{margin-top:12px}a{color:#16758b;margin-right:24px}header a{color:#b8e6f0}.card{background:white;padding:24px;border-radius:14px;box-shadow:0 3px 15px #1232;margin-bottom:20px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.kpi{font-size:36px;font-weight:700;color:#16758b}.muted{color:#52677e;font-size:14px}table{width:100%;border-collapse:collapse;font-size:14px}th,td{padding:9px;border-bottom:1px solid #dce3ed;text-align:left}th{background:#edf5f8}button{background:#16758b;color:white;border:0;border-radius:8px;padding:12px 18px;font-size:16px;cursor:pointer}input,select{font:inherit;padding:7px;width:145px;border:1px solid #abc;border-radius:5px}label{display:inline-block;margin:8px 15px 8px 0}pre{font-size:15px;line-height:1.5;white-space:pre-wrap;background:#edf5f8;padding:15px;border-radius:9px}.warn{border-left:5px solid #e4a93c}.steps{display:flex;gap:8px;flex-wrap:wrap}.steps div{background:#edf5f8;border:1px solid #88b6bf;padding:15px;border-radius:8px;flex:1;min-width:120px}footer{font-size:13px;color:#52677e;margin:30px 0}'
def page(title,body):
 return '<!doctype html><html lang="uk"><meta charset="utf-8"><title>'+title+' | CityTransit Control</title><style>'+CSS+'</style><header><h1>CityTransit Control</h1><nav><a href="/">Прогноз ETA</a><a href="/results">Перевірка якості</a><a href="/architecture">Архітектура</a><a href="/flow">Сценарії та рішення</a></nav></header><main>'+body+'<footer>Навчальний локальний прототип · Ковач Роман · Б2F201ДОН23 · Синтетичні дані · Команди транспорту не надсилаються</footer></main></html>'
class Handler(BaseHTTPRequestHandler):
 def do_GET(self):
  url=urlparse(self.path);model=json.loads((ROOT/'results/model.json').read_text());m=json.loads((ROOT/'results/metrics.json').read_text());cs=json.loads((ROOT/'results/scenarios.json').read_text())
  if url.path=='/api/predict':
   p=parse_qs(url.query);r={k:float(p[k][0]) for k in ['distance_remaining_km','speed_kmh','traffic_level','occupancy_ratio','hour','telemetry_age_sec']};r['weather']=p['weather'][0];r['record_id']='UI-'+str(time.time_ns())
   result=predict(r,model);event={'time':time.time(),'input':r,'output':result,'path':'C1-C2/C3-C4-C5-C1; C7 audit'}
   with (ROOT/'results/audit.jsonl').open('a') as f:f.write(json.dumps(event)+'\n')
   self.send_response(200);self.send_header('Content-Type','application/json');self.end_headers();self.wfile.write(json.dumps(result).encode());return
  if url.path=='/results':
   rows=''.join('<tr><td>'+c['case']+'</td><td>'+str(c['actual_eta_min'])+'</td><td>'+str(c['output']['eta_min'])+'</td><td>'+str(c['abs_error_min'])+'</td><td>'+c['output']['status']+'</td><td>'+('так' if c['policy_ok'] else 'ні')+'</td></tr>' for c in cs)
   body=f'<h2>Результати перевірки eta-ridge-v1</h2><div class="grid"><div class="card"><div class="kpi">{m["mae_min"]:.3f} хв</div>MAE моделі · 200 відкладених прикладів</div><div class="card"><div class="kpi">{m["baseline_mae_min"]:.3f} хв</div>MAE базового distance / speed</div></div><div class="card"><b>RMSE:</b> {m["rmse_min"]:.3f} хв · <b>Покриття інтервалу:</b> {m["interval_coverage"]:.1%} · <b>Політики:</b> {m["policy_passed"]}/{m["policy_total"]}<p class="muted">1200 train / 200 calibration / 200 test; різні seed. Це перевірка на синтетичному процесі, а не доказ точності в місті.</p><table><tr><th>Сценарій</th><th>Факт, хв</th><th>Прогноз</th><th>|Помилка|</th><th>Режим</th><th>Політика коректна?</th></tr>'+rows+'</table></div>'
  elif url.path=='/architecture':
   body='<h2>Від користувача до контрольованого результату</h2><div class="card"><div class="steps"><div>Пасажир / диспетчер<br>↓<br><b>C1 Інтерфейси</b></div><div><b>C5 Правила</b><br>DP-01 / DP-02 / DP-03<br>людина підтверджує дії</div><div><b>C6 Сповіщення</b><br>ETA / погоджене рішення</div></div><p>Запит ознак: C5 → C3. Відповідь: C3 → C4 → C5 → C1/C6.</p><div class="steps"><div>GPS / контекст<br>↓<br><b>C2 Якість</b><br>DP-05, DP-06</div><div><b>C3 Ознаки</b><br>distance, speed,<br>traffic, occupancy,<br>weather, hour</div><div><b>C4 AI: ETA</b><br>ridge regression<br>ETA + q90 + version</div></div></div><div class="grid"><div class="card"><b>D1</b> Операційні дані → C3<br><b>D2</b> Реєстр версій → C4<br><b>D3</b> Журнал рішень ← C7</div><div class="card"><b>C7 Аудит і контроль</b><p>Прогноз + причина + версія + факт → метрики → DP-08 / DP-09 → людина допускає модель.</p></div></div><div class="card warn">Реалізовано локальний шлях ETA та журнал. Попит, dispatch, реальні інтеграції та production-сховища залишаються проєктними компонентами.</div>'
  elif url.path=='/flow':
   body='<h2>UC-01: отримати актуальний час прибуття</h2><div class="card"><div class="steps"><div>1. Пасажир<br>обирає зупинку</div><div>2. C2/C3<br>DP-05: дані придатні?</div><div>3. C4<br>ETA + інтервал</div><div>4. C5<br>DP-01: auto / review / reject</div><div>5. C1<br>картка прибуття</div></div><h3>Відмова</h3><p>Застарілі / відсутні дані або недоступна модель → позначений розклад, без ML-прогнозу. C7 фіксує причину.</p></div><h2>UC-02: відновити інтервал</h2><div class="card"><div class="steps"><div>C3: headway</div><div>DP-04: тривога?</div><div>DP-02: диспетчер погоджує</div><div>C6: доставка</div><div>DP-10: квитанція</div></div><p>Автоматизація інформаційної відповіді не надає ШІ права відправляти команду водію.</p></div><div class="card">Специфікація: 8 use cases · 12 decision points · 12 рядків HITL. Код прототипу: UC-01 / DP-01 / частина DP-05.</div>'
  else:
   fields=[('distance_remaining_km','Відстань, км',2),('speed_kmh','Швидкість, км/год',25),('traffic_level','Затори 1–5',3),('occupancy_ratio','Заповненість 0–1',.6),('hour','Година',12),('telemetry_age_sec','Вік даних, с',10)]
   form=''.join(f'<label>{title}<br><input name="{k}" value="{v}" type="number" step="any"></label>' for k,title,v in fields)
   body='<h2>Прогноз прибуття до зупинки</h2><div class="grid"><section class="card"><h3>Вхідний зріз C3</h3><form id="f">'+form+'<label>Погода<br><select name="weather"><option>dry</option><option>rain</option><option>snow</option></select></label><p><button>Розрахувати ETA</button></p></form></section><section class="card"><h3>C4 → C5 → C1</h3><div id="result">Виконайте розрахунок</div><p class="muted">DP-01: auto_information / review / reject<br>DP-05: свіжість ≤60 с, повнота, допустимі діапазони.</p></section></div><div class="card warn"><b>Контроль людини</b><p>Публікація ETA — інформаційна дія. Затримка, випуск або зміна маршруту завжди потребують погодження диспетчера. Показаний інтервал оцінено на синтетичній вибірці.</p></div><script>document.querySelector("#f").onsubmit=async e=>{e.preventDefault();let p=new URLSearchParams(new FormData(e.target));let r=await(await fetch("/api/predict?"+p)).json();document.querySelector("#result").innerHTML=(r.eta_min===null?"<div class=kpi>Прогноз відхилено</div>":"<div class=kpi>"+r.eta_min+" хв</div><p>Інтервал: "+r.interval.join(" – ")+" хв</p>")+"<pre>"+JSON.stringify(r,null,2)+"</pre>"};document.querySelector("#f").requestSubmit();</script>'
  self.send_response(200);self.send_header('Content-Type','text/html; charset=utf-8');self.end_headers();self.wfile.write(page('Прототип ETA',body).encode())
if __name__=='__main__':HTTPServer(('127.0.0.1',18765),Handler).serve_forever()
